* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 20px;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  top: -40px; left: 8px;
  background: var(--primary);
  color: #fff;
  padding: 8px 12px;
  border-radius: 6px;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 8px; }

/* Focus styles */
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Header */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 64px;
}
.brand {
  display: inline-flex; align-items: center; gap: 8px;
  font-weight: 700; color: var(--text); text-decoration: none;
  font-size: 1.05rem;
}
.brand-mark { color: var(--primary); font-size: 1.2rem; }
.nav-list {
  list-style: none; display: flex; gap: 24px; margin: 0; padding: 0;
}
.nav-list a {
  color: var(--text-muted); text-decoration: none; font-weight: 500;
}
.nav-list a:hover { color: var(--text); }

/* Breadcrumb */
.breadcrumb { margin: 24px 0 8px; font-size: 0.9rem; }
.breadcrumb ol {
  list-style: none; padding: 0; margin: 0;
  display: flex; flex-wrap: wrap; gap: 6px;
  color: var(--text-muted);
}
.breadcrumb li + li::before {
  content: "/"; margin-right: 6px; color: var(--border-strong);
}
.breadcrumb a { color: var(--text-muted); text-decoration: none; }
.breadcrumb a:hover { color: var(--text); text-decoration: underline; }
.breadcrumb [aria-current="page"] { color: var(--text); }

/* Preview */
.preview { padding: 8px 0 64px; }
.preview-title {
  font-size: 1.75rem; margin: 8px 0 4px; font-weight: 700;
}
.preview-meta { color: var(--text-muted); margin: 0 0 20px; font-size: 0.95rem; }

.preview-figure {
  margin: 0 0 20px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 12px;
  box-shadow: var(--shadow-sm);
}
.preview-figure img {
  display: block;
  width: 100%; height: auto;
  border-radius: 8px;
  max-width: 100%;
}
.preview-figure figcaption {
  margin-top: 12px; color: var(--text-muted);
  font-size: 0.9rem; text-align: center;
}

.preview-actions {
  display: flex; flex-wrap: wrap; gap: 12px;
  justify-content: flex-end;
}

/* Buttons */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  font: inherit; font-weight: 600;
  padding: 10px 18px;
  border-radius: 8px;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background-color 0.15s, border-color 0.15s, color 0.15s;
  min-height: 40px;
