.dialog {
  background: var(--surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  width: 100%;
  max-width: 440px;
  padding: 28px 24px 20px;
  position: relative;
  animation: pop 0.15s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes pop {
  from { opacity: 0; transform: translateY(8px) scale(0.98); }
  to   { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  .dialog-backdrop, .dialog { animation: none; }
}

.dialog-icon {
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  background: var(--danger-bg);
  color: var(--danger);
  border-radius: 50%;
  margin-bottom: 14px;
}

.dialog-title {
  font-size: 1.2rem;
  margin: 0 0 8px;
  font-weight: 700;
}
.dialog-desc {
  margin: 0 0 22px;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.dialog-actions {
  display: flex; gap: 10px; justify-content: flex-end;
  flex-wrap: wrap;
}

.dialog-close {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 8px;
  color: var(--text-muted);
  cursor: pointer;
}
.dialog-close:hover { background: #eef0f4; color: var(--text); }

/* Reflow */
@media (max-width: 520px) {
  .preview-title { font-size: 1.4rem; }
  .preview-actions { justify-content: stretch; }
  .preview-actions .btn { flex: 1 1 auto; justify-content: center; }
  .nav-list { gap: 16px; }
  .dialog-actions .btn { flex: 1 1 auto; justify-content: center; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn { border: 1px solid ButtonBorder; }
  .btn-danger { background: ButtonFace; color: ButtonText; }
  .dialog { border: 1px solid CanvasText; }
  .dialog-icon { background: Canvas; color: CanvasText; border: 1px solid CanvasText; }
  :focus-visible { outline-color: Highlight; }
}
